// Official SAF IPPT scoring tables for servicemen, transcribed cell-by-cell from
// docs/ippt/Push-Up+Score+Table+for+Servicemen.pdf, Sit-Up+Score+Table+for+Servicemen.pdf
// and 2.4km+Score+Table+for+Servicemen.pdf. Do not edit by hand without re-checking the PDFs.
//
// Each row is [key, points by age group 1..14]. A null is a blank cell in the PDF: blanks only
// appear above the first maximum-points cell of a column, i.e. performance already beyond the max.
//
// Push-up / sit-up rows: key = repetitions (60 down to 1). 0 reps scores 0.
// 2.4km rows: key = run time in seconds; the PDF column header is "Time (≤)", so a row applies
// to any time less than or equal to its key and greater than the previous (faster) row's key.

export type PointsRow = readonly [key: number, points: readonly (number | null)[]];

